-- ap-server 第二期増量（クラウドサービスモデルを除く既存9カテゴリに6問ずつ追加、54問）
BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-server-q67', '稼働率とシステムの信頼性',
   '稼働率0.8のサーバーを3台用意し、すべて並列に接続した。このシステム全体の稼働率は何％か。',
   NULL::text,
   '["99.2%", "51.2%", "48.8%", "40%"]',
   0,
   '[0]',
   'single',
   '{"asked": "3台の並列接続における稼働率を計算する問題。", "why_asked": "並列の稼働率は「2台の式をそのまま3台に拡張できるか」を問う典型パターン。台数が増えても考え方は同じであることを確認する。", "kid": "3台とも同時に壊れない限り、システムは動き続ける。3台とも壊れる確率を1から引けば、動いている確率になる。", "terms": [["並列接続", "同じ役割のサーバーを複数並べ、どれか1台でも動いていればシステムが機能する接続方式"]], "think": "「動いている確率」を直接求めるのではなく、「全部止まる確率」を先に求めて1から引く、という並列稼働率の基本手順を3台に広げるだけでよい。", "calc": "問題: 稼働率0.8のサーバー3台を並列接続したときの全体稼働率を求める\nステップ1: 1台が止まっている確率を求める。1-0.8=0.2\nステップ2: 3台とも同時に止まる確率を求める。0.2×0.2×0.2=0.008\nステップ3: 1から引いて、少なくとも1台が動いている確率(全体の稼働率)を求める。1-0.008=0.992\n答え: 全体の稼働率は99.2%\n並列(3台)の稼働率 = 1-(1-A)×(1-B)×(1-C) = 1-0.2×0.2×0.2 = 1-0.008 = 0.992 = 99.2%", "vs": "0.8×0.8×0.8=51.2%は、直列接続(全部が動いていないといけない場合)の計算式を並列に誤って当てはめたもの。並列は「全部止まる確率」を考える。", "opt": ["正解。1-(1-0.8)^3 = 1-0.008 = 0.992 = 99.2%。", "0.8を3回掛けた値(0.8^3=0.512)。これは直列接続の稼働率の求め方であり、並列には当てはまらない。", "1-0.8×3のような、止まる確率を単純に3倍して引いてしまった値に近い誤り。", "1台の稼働率0.8をそのまま台数分だけ大きくしようとした値で、稼働率の計算根拠にならない。"]}'),
  ('ap-server-q68', '稼働率とシステムの信頼性',
   '稼働率0.9のサーバーA・Bを並列接続したサブシステムに、さらに稼働率0.9のサーバーCを直列につないだ。システム全体の稼働率は何％か。',
   NULL::text,
   '["89.1%", "72.9%", "97.0%", "81.0%"]',
   0,
   '[0]',
   'single',
   '{"asked": "並列サブシステムと直列サーバーが混在する構成の全体稼働率を求める問題。", "why_asked": "現実のシステムは並列と直列が組み合わさっていることが多い。「まず並列部分をひとつの稼働率にまとめてから、直列の式に入れる」という2段階の考え方ができるかを問う。", "kid": "AとBのペアをひとつの部品とみなして、その部品の稼働率を先に計算する。そのあと、その部品とCを直列でつないだときの稼働率を掛け算で求める。", "terms": [["直列接続", "複数の装置を一本道でつなぎ、どれか1つでも止まるとシステム全体が止まる接続方式"]], "think": "複合構成は一気に計算しようとせず、内側のブロック(この場合はAとBの並列部分)を先に1つの稼働率に変換してから、外側の直列計算に進む。", "calc": "問題: AとBを並列、その結果とCを直列につないだときの全体稼働率を求める\nステップ1: AとBの並列部分の稼働率を先に求める。1-(1-0.9)×(1-0.9)=1-0.01=0.99\nステップ2: この0.99を1つの部品とみなし、Cの0.9と直列でつなぐ\nステップ3: 直列は掛け算なので、0.99×0.9=0.891\n答え: 全体の稼働率は89.1%\n全体 = (1-(1-A)×(1-B)) × C = (1-0.1×0.1) × 0.9 = 0.99 × 0.9 = 0.891 = 89.1%", "eg": "たとえるなら、AとBのペアは「二重の見張り番」で、そのペア全体が1つの門番だと考える。その門番Cという別の門番と2つ連続で通らないといけない、という構造。", "vs": "0.9×0.9×0.9=72.9%は、AとBの並列関係を無視してA・B・Cすべてを直列扱いしてしまった誤り。", "opt": ["正解。並列部分(AとB)を先に0.99にまとめ、Cと直列で0.99×0.9=0.891。", "A・B・Cをすべて直列とみなして0.9を3回掛けた値(0.9^3=0.729)。AとBが並列であることが反映されていない。", "並列部分の稼働率0.99をそのまま全体の答えにしてしまい、Cとの直列接続を反映し忘れた値に近い。", "0.9×0.9=0.81に類する値で、Cとの組み合わせ方が正しく計算されていない。"]}'),
  ('ap-server-q69', '稼働率とシステムの信頼性',
   '稼働率99.9%（いわゆる「スリーナイン」）のシステムが1年間（365日）に停止してもよい時間は、おおよそ何時間か。',
   NULL::text,
   '["約8.8時間", "約87.6時間", "約0.9時間", "約36.5時間"]',
   0,
   '[0]',
   'single',
   '{"asked": "稼働率(%)から、1年間に許容される停止時間を逆算する問題。", "why_asked": "「稼働率99.9%」のような数字を、実際の停止時間という感覚に変換できるかを問う。SLA（サービス品質保証）でもよく使われる考え方。", "kid": "1年は365日×24時間で8760時間ある。稼働率99.9%ということは、そのうち0.1%だけ止まってもよい、という意味。8760時間の0.1%を計算すればよい。", "terms": [["稼働率", "全体の時間のうち、実際にシステムが動いていた時間の割合"]], "think": "「稼働率99.9%」を「停止が許される割合は100%-99.9%=0.1%」と読み替えてから、1年間の総時間にその割合を掛ける。", "calc": "問題: 稼働率99.9%のシステムが1年間に停止してよい時間を求める\nステップ1: 1年間の総時間を求める。365日×24時間=8760時間\nステップ2: 停止が許される割合を求める。100%-99.9%=0.1%=0.001\nステップ3: 8760時間×0.001=8.76時間\n答え: 1年間に許容される停止時間は約8.8時間\n許容停止時間 = 年間総時間 × (1-稼働率) = 8760時間 × 0.001 ≒ 8.8時間", "vs": "約87.6時間は、稼働率99%(0.1%ではなく1%停止可)の場合の値と混同している。「99.9%」の「9」の個数で桁が1つ変わることに注意。", "opt": ["正解。8760時間×0.1%＝8.76時間で、約8.8時間となる。", "稼働率99%(停止許容1%)の場合の停止時間(約87.6時間)であり、99.9%の桁を1つ読み違えている。", "8760時間の0.01%程度の小さすぎる値で、0.1%の計算になっていない。", "365日の0.1%(0.365日)を時間換算しただけの値で、24時間を掛け忘れている。"]}'),
  ('ap-server-q70', '稼働率とシステムの信頼性',
   'MTBF（平均故障間隔）180時間、MTTR（平均修復時間）20時間のサーバーに対し、保守体制を改善してMTTRだけを10時間に短縮した。稼働率はどう変化するか。',
   NULL::text,
   '["90%から約94.7%に上がる", "90%から80%に下がる", "変化しない", "90%から95%に上がる"]',
   0,
   '[0]',
   'single',
   '{"asked": "MTTRの短縮が稼働率に与える影響を、実際の数値で確認する問題。", "why_asked": "「稼働率を上げるには壊れにくくする（MTBFを伸ばす）か、直すのを速くする（MTTRを縮める）かの2つの方向がある」という理解を、片方だけ変えた具体例で確認する。", "kid": "MTTR（直すのにかかる時間）が短くなれば、故障していない時間の割合が増えるので、稼働率は上がる。", "terms": [["MTTR", "故障してから修理が完了して復旧するまでの平均時間"]], "think": "稼働率=MTBF÷(MTBF+MTTR)の式に、MTTRだけを10に変えた値を入れて計算し、元の90%と比べる。", "calc": "問題: MTBF=180時間のまま、MTTRを20時間から10時間に短縮したときの稼働率を求める\nステップ1: 元の稼働率を確認する。180÷(180+20)=180÷200=0.9=90%\nステップ2: MTTR=10時間での稼働率を計算する。180÷(180+10)=180÷190\nステップ3: 180÷190を計算すると、約0.947＝94.7%\n答え: 稼働率は90%から約94.7%に上がる\n稼働率 = MTBF÷(MTBF+MTTR) = 180÷190 ≒ 0.947 = 約94.7%", "vs": "MTBFを伸ばす方向（壊れにくくする）とMTTRを縮める方向（直すのを速くする）は、どちらも稼働率を上げるが、この問題はMTTR側だけを変えている点に注意する。", "opt": ["正解。180÷190≒0.947で、90%から約94.7%に上がる。", "MTTRを短縮しているのに稼働率が下がるという、式の意味を逆に捉えた値。", "MTTRを変えても稼働率は変わらないというのは誤り。MTTRは稼働率の式の分母に入っている。", "計算の方向性は正しいが数値がわずかにずれている。180÷190を正しく計算すると94.7%程度になる。"]}'),
  ('ap-server-q71', '稼働率とシステムの信頼性',
   '稼働率0.95のサーバーを2台並列で冗長化したが、両方のサーバーが共有している電源装置（稼働率0.9）が1つしかない。システム全体の稼働率は何％か。',
   NULL::text,
   '["約89.8%", "約99.75%", "約85.5%", "約95%"]',
   0,
   '[0]',
   'single',
   '{"asked": "並列冗長化した部分と、共有している単一の部品（電源）を直列で組み合わせたときの全体稼働率を求める問題。", "why_asked": "「サーバーを並列化して冗長化した」つもりでも、共有している電源やネットワーク機器が1つしかなければ、そこが全体の足を引っ張るという実務上の落とし穴を数値で理解させる。", "kid": "サーバー2台はお互いに保険になっているので壊れにくいが、電源はどちらのサーバーにとっても共通の1本道。電源が止まれば、サーバーが何台あっても全部止まる。", "terms": [["単一障害点（SPOF）", "そこが壊れるとシステム全体が止まってしまう、冗長化されていない箇所"]], "think": "サーバー2台の並列部分を先に1つの稼働率にまとめ、それを共有の電源と直列でつなぐ、という2段階の計算になる。電源は1つしかないので冗長化されていない点に注意する。", "calc": "問題: 稼働率0.95のサーバー2台を並列化し、共有の電源(稼働率0.9)と直列でつないだときの全体稼働率を求める\nステップ1: サーバー2台の並列部分の稼働率を求める。1-(1-0.95)×(1-0.95)=1-0.0025=0.9975\nステップ2: この0.9975を電源(0.9)と直列でつなぐので、掛け算する\nステップ3: 0.9975×0.9=0.89775\n答え: 全体の稼働率は約89.8%\n全体 = (1-(1-0.95)^2) × 0.9電源 = 0.9975 × 0.9 ≒ 0.898 = 約89.8%", "vs": "サーバー部分だけの稼働率(約99.75%)を見て満足してしまい、共有の電源という単一障害点を見落とすと、全体の稼働率を過大評価してしまう。", "opt": ["正解。サーバー並列部分0.9975と電源0.9を直列で掛け合わせ、約89.8%になる。", "サーバー2台の並列部分だけの稼働率(0.9975)で、電源という共有の単一障害点の影響を反映し忘れている。", "電源の影響を過大に見積もりすぎた値で、サーバー側の冗長化の効果が十分に反映されていない。", "サーバー1台単体の稼働率のままで、並列化も電源との直列接続も反映されていない。"]}'),
  ('ap-server-q72', '稼働率とシステムの信頼性',
   'システムの稼働率を高める方法として、「同じ装置をもう1台用意して並列にする」以外の方向性として最も適切なものはどれか。',
   NULL::text,
   '["個々の装置の壊れにくさ（MTBF）を高める", "MTBFを下げてでも装置を増やす", "MTTRをあえて長く取る", "並列にする台数をひたすら増やし続ける以外に手段はない"]',
   0,
   '[0]',
   'single',
   '{"asked": "稼働率を上げるアプローチが「並列化（台数を増やす）」以外にもあることを理解しているかを問う概念問題。", "why_asked": "稼働率の計算問題ばかりを解いていると「稼働率を上げる＝台数を増やす」という発想に偏りがちだが、個々の装置自体の品質（MTBFを伸ばす、MTTRを縮める）を高める方向性も同じくらい重要であることを確認する。", "kid": "稼働率を上げる方法は大きく2つ。1つは「壊れても困らないように装置を増やす（並列化）」、もう1つは「そもそも壊れにくくする・直すのを速くする（個々の装置の品質を上げる）」。", "terms": [["MTBF", "壊れてから次に壊れるまでの平均間隔。長いほど壊れにくい"]], "think": "稼働率=MTBF÷(MTBF+MTTR)の式を思い出せば、台数を増やさなくてもMTBFを伸ばす・MTTRを縮めることで稼働率が上がることが分かる。", "vs": "「並列化」と「個々の装置の品質向上」はどちらも有効な方向性で、対立するものではなく組み合わせて使うのが実務では一般的。", "opt": ["正解。個々の装置が壊れにくくなれば、台数を増やさなくても稼働率は上がる。", "MTBFを下げる（壊れやすくする）ことは稼働率を下げる方向であり、逆効果になる。", "MTTRを長くする（直すのに時間がかかるようにする）ことは稼働率を下げる方向であり、逆効果になる。", "並列化以外にも、MTBFを伸ばす・MTTRを縮めるという個々の装置の品質を高める方向性がある。"]}'),
  ('ap-server-q73', 'RAIDの仕組みと計算',
   'RAID5ではパリティによって1台の故障まで耐えられるのに対し、2台同時に故障してもデータを守れるように、パリティを2重に持つRAID構成を何というか。',
   NULL::text,
   '["RAID6", "RAID0", "RAID1", "RAID5+"]',
   0,
   '[0]',
   'single',
   '{"asked": "2台同時の故障に耐えられるRAID構成の名称を問う問題。", "why_asked": "RAID5の「パリティ1台分」という発想を、そのまま「パリティ2台分」に拡張した構成があることを知っているかを確認する。", "kid": "RAID5は誤り訂正用の情報（パリティ）を1台分だけ持つので、1台の故障までしか耐えられない。RAID6はこのパリティを2台分に増やすことで、2台同時に故障してもデータを復元できるようにした構成。", "terms": [["パリティ", "元のデータから計算される誤り訂正用の情報。故障したディスクのデータを復元するために使う"]], "think": "「パリティを何台分持つか」でRAID5とRAID6の違いを整理すると覚えやすい。RAID5＝1台分、RAID6＝2台分。", "vs": "RAID5と混同しやすいが、RAID6はディスク台数が同じでも実効容量がさらに1台分少なくなる（パリティ2台分を引く）というトレードオフがある。", "opt": ["正解。RAID6はパリティを2台分持つことで、2台同時の故障に耐えられる。", "RAID0はデータを分散して高速化する構成で、そもそも冗長性（保険）を持たない。", "RAID1は同じデータを複製するミラーリングであり、パリティという仕組みは使わない。", "「RAID5+」という標準的な名称のRAID構成は存在しない。"]}'),
  ('ap-server-q74', 'RAIDの仕組みと計算',
   '容量250GBのディスクを6台用意し、RAID6（2重パリティ）を構成した。このとき実際にデータの保存に使える容量（実効容量）は何GBか。',
   NULL::text,
   '["1000GB", "1250GB", "1500GB", "750GB"]',
   0,
   '[0]',
   'single',
   '{"asked": "RAID6構成時の実効容量を計算する問題。", "why_asked": "RAID5の「台数-1」という実効容量の式を、RAID6では「台数-2」に置き換えて計算できるかを確認する。", "kid": "RAID6は6台のうち2台分がパリティ（保険）用に使われる。だから実際にデータを保存できるのは、残りの4台分だけ。", "terms": [["実効容量", "実際にデータの保存に使える容量。RAID6では全体からパリティ2台分を引いた量になる"]], "think": "RAID5の「(台数-1)×1台分の容量」という式のマイナス部分を「2」に変えるだけでよい。パリティが2台分になったことがそのまま式に反映される。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">RAID6：250GB×6台の内訳</text><rect x=\"10\" y=\"40\" width=\"48\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"63\" y=\"40\" width=\"48\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"116\" y=\"40\" width=\"48\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"169\" y=\"40\" width=\"48\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"222\" y=\"40\" width=\"48\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><rect x=\"275\" y=\"40\" width=\"48\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"34\" y=\"62\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\">データ</text><text x=\"87\" y=\"62\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\">データ</text><text x=\"140\" y=\"62\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\">データ</text><text x=\"193\" y=\"62\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\">データ</text><text x=\"246\" y=\"62\" font-size=\"8.5\" fill=\"#c9a04a\" text-anchor=\"middle\">パリティ1</text><text x=\"299\" y=\"62\" font-size=\"8.5\" fill=\"#c9a04a\" text-anchor=\"middle\">パリティ2</text><text x=\"170\" y=\"118\" font-size=\"10.5\" fill=\"#8892a4\" text-anchor=\"middle\">6台のうち2台分をパリティに回す → 実効容量は4台分</text></svg>", "calc": "問題: 250GBのディスクを6台使ってRAID6を組んだときの実効容量を求める\nステップ1: RAID6の実効容量は「台数-2」台分になる、というルールを確認する\nステップ2: 台数は6台なので、6-2=4台分がデータ保存に使える\nステップ3: 4台×250GB=1000GB\n答え: 実効容量は1000GB\nRAID6の実効容量 = (台数-2) × 1台あたりの容量 = (6-2) × 250GB = 4 × 250GB = 1000GB", "vs": "RAID5の式（台数-1）とそのまま同じ式を使ってしまうと1250GBという誤った値になる。RAID6はパリティが2台分であることを忘れない。", "opt": ["正解。(6-2)×250GB=4×250GB=1000GB。", "RAID5の式（台数-1）をそのまま使ってしまった値。(6-1)×250GB=1250GBで、パリティが2台分であることが反映されていない。", "パリティを考慮せず6台分をそのまま合計してしまった値に近い誤り。", "台数を半分にしてRAID1のように計算してしまった値に近い誤り。"]}'),
  ('ap-server-q75', 'RAIDの仕組みと計算',
   '複数のディスクにデータを高速に分散して書き込む「ストライピング」と、同じデータを複製する「ミラーリング」を組み合わせたRAID構成を何というか。',
   NULL::text,
   '["RAID10（RAID1+0）", "RAID5", "RAID6", "JBOD"]',
   0,
   '[0]',
   'single',
   '{"asked": "ストライピングとミラーリングを組み合わせたRAID構成の名称を問う問題。", "why_asked": "RAID0（速度）とRAID1（保護）の「良いとこ取り」をした構成があることを知っているかを確認する。実務でもデータベースサーバーなどでよく使われる。", "kid": "RAID10は、まずディスクをペアにしてミラーリング（RAID1）で保護し、そのペアをさらに複数組並べてストライピング（RAID0）で高速化する、二段構えの構成。", "terms": [["ストライピング", "データを複数のディスクに分散して書き込み、読み書きを高速化する仕組み（RAID0の考え方）"], ["ミラーリング", "同じデータを複数のディスクに複製して保護する仕組み（RAID1の考え方）"]], "think": "RAID0は速いが壊れやすい、RAID1は堅いが容量効率が悪い。この2つを掛け合わせることで「速くて、かつ保護もある」構成を作る、という発想がRAID10。", "vs": "RAID5もデータ保護と速度のバランスを取る構成だが、RAID10はミラーリングをベースにしている点でRAID5（パリティ方式）と仕組みが異なる。一般にRAID10の方が復旧が速く、書き込み性能も高い。", "opt": ["正解。RAID10はミラーリング（RAID1）とストライピング（RAID0）を組み合わせた構成。", "RAID5はパリティ分散によって保護と容量効率のバランスを取る構成で、ミラーリングは使わない。", "RAID6はパリティを2重にした構成で、ミラーリングとストライピングの組み合わせではない。", "JBODは複数のディスクを単純に連結するだけの方式で、速度向上も保護の仕組みも持たない。"]}'),
  ('ap-server-q76', 'RAIDの仕組みと計算',
   '容量500GBのディスクを8台用意し、RAID10（4組のミラーリングをストライピング）を構成した。このとき実際にデータの保存に使える容量（実効容量）は何GBか。',
   NULL::text,
   '["2000GB", "4000GB", "500GB", "3500GB"]',
   0,
   '[0]',
   'single',
   '{"asked": "RAID10構成時の実効容量を計算する問題。", "why_asked": "RAID10の実効容量は「RAID1（半分になる）」の考え方をそのまま台数分に広げれば求められることを確認する。", "kid": "RAID10は2台1組のペアでミラーリングしているので、常に半分の台数分しか使えない。8台なら、実際に使えるのは4台分。", "terms": [["RAID10の実効容量", "台数の半分×1台分の容量（何組のペアを作ってストライピングしても、半分になるのは変わらない）"]], "think": "RAID1が「台数を増やしても実効容量は変わらず1台分」だったのに対し、RAID10は「複数のペアを並べる」ため、台数が増えれば実効容量も増える。ただし常に台数の半分にとどまる。", "calc": "問題: 500GBのディスク8台でRAID10を組んだときの実効容量を求める\nステップ1: RAID10は2台1組のミラーペアをストライピングで束ねる構成だと確認する\nステップ2: 8台なので、ペアの数は8÷2=4組。実効容量は4台分\nステップ3: 4台×500GB=2000GB\n答え: 実効容量は2000GB\nRAID10の実効容量 = (台数÷2) × 1台あたりの容量 = (8÷2) × 500GB = 4 × 500GB = 2000GB", "vs": "8台分をそのまま合計した4000GBは、ミラーリングによる保護分を考慮していないRAID0の計算に近い誤り。", "opt": ["正解。8台の半分の4台分が使え、4×500GB=2000GB。", "ミラーリングを考慮せず8台分をそのまま合計してしまった値(8×500GB=4000GB)。", "RAID1のように「台数によらず1台分だけ」という考え方を誤って適用した値。", "8台のうち1台分をパリティのように引いてしまった、RAID5の考え方を誤って混ぜた値。"]}'),
  ('ap-server-q77', 'RAIDの仕組みと計算',
   'RAID5を構成する複数のディスクのうち1台が故障し、新しいディスクに交換してデータを再構築（リビルド）している最中に、特に注意すべきこととして最も適切なものはどれか。',
   NULL::text,
   '["残りのディスクへの負荷が高まり、その間にもう1台が故障するとデータを失うリスクが上がる", "リビルド中はディスクへの負荷がむしろ下がるので、特に注意することはない", "リビルド中はRAID5の実効容量が一時的に増える", "リビルドが完了するまでは、システムを稼働させたまま使うことはできない"]',
   0,
   '[0]',
   'single',
   '{"asked": "RAID5のリビルド中に起きるリスクについて問う概念問題。", "why_asked": "RAID5の「1台まで耐えられる」という安心感の裏にある、リビルド中の追加リスクという実務上の重要な注意点を問う。", "kid": "壊れた1台分のデータをパリティから計算して復元するリビルド作業は、残りのすべてのディスクを全部読み直す必要があるため、ふだんより負荷が高くなる。負荷が高い状態が続くと、他のディスクも壊れやすくなるタイミングでもある。", "terms": [["リビルド", "故障したディスクを交換した後、パリティなどから元のデータを計算して復元する処理"]], "think": "RAID5は「1台までの故障に耐えられる」が、リビルド中に2台目が壊れるとその耐性を使い切ってしまい、データを失う。だからこそ、故障台数が多いRAID6やRAID10が選ばれる場面がある。", "vs": "RAID6が好まれる理由の1つは、まさにこのリビルド中のリスクに対して、もう1台分の余裕（2台まで耐えられる）を持っていること。", "opt": ["正解。リビルド中は全ディスクへの読み込み負荷が高まり、その間の追加故障でデータを失うリスクが上がる。", "リビルド中は残りのディスクを総動員してデータを復元するため、負荷はむしろ上がる。", "リビルド中に実効容量が増えることはなく、故障したディスク分は使えないままである。", "多くのRAID5構成ではリビルド中も稼働を続けたまま使用できるが、性能が低下することが多い。"]}'),
  ('ap-server-q78', 'RAIDの仕組みと計算',
   '容量1TBのディスクを3台用意し、すべて同じデータを複製するRAID1（3面ミラーリング）を構成した。このとき実際にデータの保存に使える容量（実効容量）は何TBか。',
   NULL::text,
   '["1TB", "3TB", "2TB", "1.5TB"]',
   0,
   '[0]',
   'single',
   '{"asked": "3台構成のRAID1（3面ミラーリング）における実効容量を計算する問題。", "why_asked": "「RAID1の実効容量は台数によらず1台分」という原則が、2台だけでなく3台以上に増やしても変わらないことを確認する。", "kid": "3台とも同じデータをそのままコピーしているだけなので、3台合わせても保存できる情報量は1台分と変わらない。台数を増やしたのは容量を増やすためではなく、同時に2台壊れても耐えられるようにするため。", "terms": [["3面ミラーリング", "同じデータを3台のディスクに複製すること。2台同時に故障してもデータを守れる"]], "think": "RAID1は「容量ではなく保険を買っている」構成だという考え方は、ペアが2台でも3台でも変わらない。台数が増えるほど保険は厚くなるが、実効容量は常に1台分のまま。", "calc": "問題: 1TBのディスク3台で3面ミラーリング（RAID1）を組んだときの実効容量を求める\nステップ1: RAID1は台数を増やしても、実効容量は1台分のままというルールを確認する\nステップ2: 3台とも同じデータの複製なので、使える容量は1台分の1TB\n答え: 実効容量は1TB\nRAID1（N面ミラー）の実効容量 = ディスク1台分の容量 = 1TB（台数を増やしても変わらない）", "vs": "2台のRAID1と同じ感覚で「台数分だけ容量が増える」と考えてしまうと、3TBという誤った値になる。ミラーリングは常に容量ではなく保険を積み増している。", "opt": ["正解。3台とも同じデータの複製なので、実効容量は1台分の1TBのまま。", "3台分をそのまま合計してしまった値で、ミラーリングによる複製であることが反映されていない。", "台数と実効容量が比例するという誤った前提に基づく値。", "3台のうち1台分をパリティのように引いてしまった、RAID5の考え方を誤って混ぜた値。"]}'),
  ('ap-server-q79', '負荷分散と高可用性設計',
   'ロードバランサが、各サーバーに定期的に疑似的なアクセスを送るなどして「そのサーバーが正常に応答できる状態か」を継続的に確認する仕組みを何というか。',
   NULL::text,
   '["ヘルスチェック", "ラウンドロビン", "フェイルオーバー", "スティッキーセッション"]',
   0,
   '[0]',
   'single',
   '{"asked": "ロードバランサがサーバーの生死・正常性を確認する仕組みの名称を問う問題。", "why_asked": "「ロードバランサは振り分けるだけの装置」という理解で止まらず、振り分け先が正常かどうかを見極める仕組みがあって初めて高可用性が成り立つことを理解しているかを確認する。", "kid": "ロードバランサは、各サーバーに「元気ですか」と定期的に聞きに行っている。返事がなかったり、変な返事が返ってきたりしたサーバーは、振り分け先から一時的に外す。", "terms": [["ヘルスチェック", "ロードバランサが各サーバーの正常性を定期的に確認する仕組み"]], "think": "ヘルスチェックがなければ、ロードバランサは故障したサーバーにもリクエストを送り続けてしまう。異常なサーバーを自動的に振り分け先から外すために必須の仕組み。", "vs": "ラウンドロビンは「どう振り分けるか」の方式であり、ヘルスチェックは「振り分け先が正常かどうか」を確認する仕組みで、役割が異なる。", "opt": ["正解。ヘルスチェックは、各サーバーの正常性を定期的に確認する仕組み。", "ラウンドロビンは、サーバーへ順番に均等にリクエストを振り分ける方式のこと。", "フェイルオーバーは、故障が起きたときに別の系統へ切り替える動作そのものを指す。", "スティッキーセッションは、同じ利用者からのリクエストを毎回同じサーバーに送る仕組みのこと。"]}'),
  ('ap-server-q80', '負荷分散と高可用性設計',
   'ロードバランサの振り分け方式のうち、各サーバーが現在処理している接続数を見て、最も接続数が少ないサーバーに新しいリクエストを送る方式を何というか。',
   NULL::text,
   '["最小コネクション方式", "ラウンドロビン方式", "IPハッシュ方式", "ランダム方式"]',
   0,
   '[0]',
   'single',
   '{"asked": "接続数に応じてリクエストを振り分ける方式の名称を問う問題。", "why_asked": "ラウンドロビン（順番に均等に振る）だけでなく、サーバーの実際の負荷状況を見て振り分ける方式もあることを理解しているかを確認する。処理に時間のかかるリクエストが混ざる実務では特に重要。", "kid": "ラウンドロビンは「順番に均等に」割り振るだけなので、あるサーバーがたまたま重い処理を抱えていても気にせず割り振ってしまう。最小コネクション方式は「今いちばん暇なサーバー」を見て割り振るので、より実態に合った分散ができる。", "terms": [["コネクション数", "そのサーバーが現在処理中の接続の数"]], "think": "ラウンドロビンは「振り分けた回数」だけを見るのに対し、最小コネクション方式は「今どれだけ処理中か」という実際の負荷を見て判断する、という違いを押さえる。", "vs": "ラウンドロビンは実装がシンプルで軽量な反面、処理時間にばらつきがあるとサーバー間の負荷が偏りやすい。最小コネクション方式はその偏りを是正しやすい。", "opt": ["正解。最小コネクション方式は、現在の接続数が最も少ないサーバーに振り分ける。", "ラウンドロビン方式は、接続数を見ずに順番へ均等に振り分ける方式。", "IPハッシュ方式は、送信元IPアドレスなどから計算した値で振り分け先を決める、スティッキーセッション寄りの方式。", "ランダム方式は、接続数を考慮せずくじ引きのように振り分け先を決める方式。"]}'),
  ('ap-server-q81', '負荷分散と高可用性設計',
   'Active-Standby構成で、稼働中のサーバーに障害が発生したとき、待機系サーバーへ自動的に処理を引き継ぐ動作を何というか。',
   NULL::text,
   '["フェイルオーバー", "フェイルバック", "ロードバランシング", "クラスタリング"]',
   0,
   '[0]',
   'single',
   '{"asked": "Active-Standby構成における障害発生時の切り替え動作の名称を問う問題。", "why_asked": "「Active-Standby構成を作ること」自体と、「実際に切り替わる動作」を区別して理解できているかを確認する。", "kid": "普段は1台（Active）だけが働き、もう1台（Standby）は電源を入れたまま待機している。Activeが壊れたとき、Standbyがすぐに代わりを引き継ぐ、その切り替え動作自体をフェイルオーバーと呼ぶ。", "terms": [["フェイルオーバー", "障害発生時に、稼働系から待機系へ自動的に処理を引き継ぐ動作"], ["フェイルバック", "障害から復旧した後、元の稼働系にもう一度処理を戻す動作"]], "think": "「Active-Standby」は構成（体制）の名前、「フェイルオーバー」はその体制の中で実際に起きる切り替え動作の名前、と役割を分けて覚える。", "vs": "フェイルオーバーと混同しやすい「フェイルバック」は、復旧後に元のサーバーへ処理を戻す、逆方向の動作を指す。", "opt": ["正解。フェイルオーバーは、障害発生時に待機系へ自動的に処理を引き継ぐ動作。", "フェイルバックは、障害から復旧した後に元の稼働系へ処理を戻す、逆方向の動作。", "ロードバランシングは、複数のサーバーへ処理を振り分けることそのものを指す、別の概念。", "クラスタリングは、複数台のサーバーをまとめて1つのシステムのように動かす仕組み全体を指す言葉。"]}'),
  ('ap-server-q82', '負荷分散と高可用性設計',
   '通常の処理に必要な台数がN台のとき、あらかじめ1台分の予備を余分に用意しておく冗長構成の考え方を何というか。',
   NULL::text,
   '["N+1冗長化", "N×2冗長化", "N-1冗長化", "フルミラー冗長化"]',
